create table referral_program (id uuid primary key, name varchar(64) not null, version integer not null, reward_amount numeric(19,4) not null, currency varchar(3) not null, qualifying_event varchar(128) not null, attribution_window_ends_at timestamptz not null, status varchar(16) not null, maker varchar(255) not null, checker varchar(255), created_at timestamptz not null, published_at timestamptz, unique(name,version));
create table referral_invite (id uuid primary key, program_id uuid not null references referral_program(id), token_hash varchar(64) not null unique, referrer_party_id uuid not null, referee_party_id uuid, status varchar(16) not null, expires_at timestamptz not null, idempotency_key varchar(255) not null unique, attributed_at timestamptz);
create table referral_reward (id uuid primary key, invite_id uuid not null references referral_invite(id), program_id uuid not null references referral_program(id), referrer_party_id uuid not null, referee_party_id uuid not null, qualification_event_id varchar(255) not null, reward_reference varchar(255) not null unique, amount numeric(19,4) not null, currency varchar(3) not null, status varchar(32) not null, created_at timestamptz not null, requested_at timestamptz, rewarded_at timestamptz, unique(invite_id,qualification_event_id));
create table referral_audit_event (id uuid primary key, type varchar(64) not null, aggregate_id uuid not null, actor varchar(255) not null, details text not null, occurred_at timestamptz not null);
create index referral_invite_program_idx on referral_invite(program_id);
create index referral_audit_aggregate_idx on referral_audit_event(aggregate_id,occurred_at);
